import org.apache.commons.lang3.math.Fraction;

public class Probe {
    public static void main(String[] args) throws Exception {
        p("getFraction(0.5)", Fraction.getFraction(0.5));
        p("getFraction(1.0/3.0)", Fraction.getFraction(1.0/3.0));
        p("getFraction(-0.5)", Fraction.getFraction(-0.5));
        try { Fraction.getFraction(Double.NaN); System.out.println("NaN: no throw"); } catch (ArithmeticException e) { System.out.println("NaN throws: " + e.getMessage()); }
        try { Fraction.getFraction((double) Integer.MAX_VALUE + 10000.0); System.out.println("big: no throw"); } catch (ArithmeticException e) { System.out.println("big throws: " + e.getMessage()); }

        try { Fraction.getFraction(1, 0); System.out.println("1/0 no throw"); } catch (ArithmeticException e) { System.out.println("1/0 throws " + e.getMessage()); }
        try { Fraction f = Fraction.getFraction(Integer.MIN_VALUE, -1); System.out.println("MIN,-1 -> " + f); } catch (ArithmeticException e) { System.out.println("MIN,-1 throws " + e.getMessage()); }
        try { Fraction f = Fraction.getFraction(1, Integer.MIN_VALUE); System.out.println("1,MIN -> " + f); } catch (ArithmeticException e) { System.out.println("1,MIN throws " + e.getMessage()); }
        p("getFraction(3,-4)", Fraction.getFraction(3, -4));

        try { Fraction f = Fraction.getFraction(-1, 3, 4); System.out.println("whole-1,3,4 -> " + f); } catch (Exception e) { System.out.println("whole-1,3,4 throws " + e); }
        try { Fraction.getFraction(1, -3, 4); System.out.println("no throw numer neg"); } catch (ArithmeticException e) { System.out.println("numer neg throws " + e.getMessage()); }
        try { Fraction.getFraction(1, 3, -4); System.out.println("no throw denom neg"); } catch (ArithmeticException e) { System.out.println("denom neg throws " + e.getMessage()); }
        try { Fraction f = Fraction.getFraction(Integer.MAX_VALUE, 1, 2); System.out.println("overflow -> " + f); } catch (ArithmeticException e) { System.out.println("overflow throws " + e.getMessage()); }

        p("getFraction(\"1 3/4\")", Fraction.getFraction("1 3/4"));
        p("getFraction(\"7\")", Fraction.getFraction("7"));
        try { Fraction.getFraction("1 3"); System.out.println("no throw"); } catch (NumberFormatException e) { System.out.println("'1 3' throws " + e.getMessage()); }
        try { Fraction.getFraction("1/0"); System.out.println("no throw"); } catch (ArithmeticException e) { System.out.println("'1/0' throws " + e.getMessage()); }
        try { Fraction.getFraction((String) null); System.out.println("no throw"); } catch (NullPointerException e) { System.out.println("null throws " + e); }

        p("getReducedFraction(4, Integer.MIN_VALUE)", Fraction.getReducedFraction(4, Integer.MIN_VALUE));
        p("getReducedFraction(Integer.MIN_VALUE, 1)", Fraction.getReducedFraction(Integer.MIN_VALUE, 1));
        p("getReducedFraction(-4,-8)", Fraction.getReducedFraction(-4, -8));

        try { Fraction.getFraction(Integer.MAX_VALUE, 1).add(Fraction.getFraction(1, 1)); System.out.println("add no throw"); } catch (ArithmeticException e) { System.out.println("add overflow throws " + e.getMessage()); }
        try { Fraction.getFraction(Integer.MAX_VALUE, 1).multiplyBy(Fraction.getFraction(2, 1)); System.out.println("mul no throw"); } catch (ArithmeticException e) { System.out.println("mul overflow throws " + e.getMessage()); }

        p("divideBy", Fraction.getFraction(1, 2).divideBy(Fraction.getFraction(1, 4)));
        try { Fraction.getFraction(1, 2).divideBy(Fraction.ZERO); System.out.println("no throw"); } catch (ArithmeticException e) { System.out.println("div0 throws " + e.getMessage()); }

        try { Fraction.getFraction(Integer.MIN_VALUE, 1).invert(); System.out.println("no throw"); } catch (ArithmeticException e) { System.out.println("invert MIN throws " + e.getMessage()); }
        p("invert(-3,4)", Fraction.getFraction(-3, 4).invert());
        try { Fraction.ZERO.invert(); System.out.println("no throw"); } catch (ArithmeticException e) { System.out.println("invert zero throws " + e.getMessage()); }

        try { Fraction.getFraction(Integer.MIN_VALUE, 1).negate(); System.out.println("no throw"); } catch (ArithmeticException e) { System.out.println("negate MIN throws " + e.getMessage()); }

        p("abs same instance?", Fraction.getFraction(3,4) == Fraction.getFraction(3,4).abs() ? "n/a" : "n/a");
        Fraction pos = Fraction.getFraction(3,4);
        System.out.println("abs returns same instance: " + (pos.abs() == pos));

        p("pow(2,3 ^2)", Fraction.getFraction(2, 3).pow(2));
        Fraction base = Fraction.getFraction(2,3);
        System.out.println("pow(1) same instance: " + (base.pow(1) == base));
        p("pow(0)", Fraction.getFraction(2,3).pow(0));
        p("pow(-1) of 2/3", Fraction.getFraction(2,3).pow(-1));
        p("pow(-2) of 1/2", Fraction.getFraction(1,2).pow(-2));
        p("ONE.pow(MIN_VALUE)", Fraction.ONE.pow(Integer.MIN_VALUE));

        System.out.println("compareTo equalvalue: " + Fraction.getFraction(1,2).compareTo(Fraction.getFraction(2,4)));
        System.out.println("equals 1/2 vs 2/4: " + Fraction.getFraction(1,2).equals(Fraction.getFraction(2,4)));

        p("toProperString 7/4", Fraction.getFraction(7,4));
        System.out.println("toProperString 7/4: " + Fraction.getFraction(7,4).toProperString());
        System.out.println("toProperString -7/4: " + Fraction.getFraction(-7,4).toProperString());
        System.out.println("toProperString 0/5: " + Fraction.getFraction(0,5).toProperString());
        System.out.println("toProperString 4/4: " + Fraction.getFraction(4,4).toProperString());
        System.out.println("toProperString -4/4: " + Fraction.getFraction(-4,4).toProperString());

        System.out.println("getProperWhole(7,4): " + Fraction.getFraction(7,4).getProperWhole());
        System.out.println("getProperNumerator(7,4): " + Fraction.getFraction(7,4).getProperNumerator());
        System.out.println("getProperWhole(-7,4): " + Fraction.getFraction(-7,4).getProperWhole());
        System.out.println("getProperNumerator(-7,4): " + Fraction.getFraction(-7,4).getProperNumerator());

        System.out.println("doubleValue(1,3): " + Fraction.getFraction(1,3).doubleValue());
        System.out.println("floatValue(1,3): " + Fraction.getFraction(1,3).floatValue());
    }
    static void p(String label, Object o) { System.out.println(label + " -> " + o); }
}
